// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // 1. bound amount to avoid overflow concerns, keep it wide
        amount = bound(amount, 0, type(uint256).max - 1);
        // 2. initialize the contract to have a valid setup
        c.init(address(1), address(2), address(3));
        // record the value before the call
        uint256 countBefore = c.proposalCount();
        // call newGrantProposal
        bool ok = true;
        try c.newGrantProposal(recipient, amount) { ok = true; } catch { ok = false; }
        // 3. assertion: if the call succeeded, the proposalCount must have increased by exactly 1
        assertTrue(!ok || c.proposalCount() == countBefore + 1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint amount) public {
        vm.assume(recipient != address(0));
        c.init(address(0x1), address(0x2), address(0x3));
        uint oldCount = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint newCount = c.proposalCount();
        assertTrue(newCount == oldCount + 1);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address vader, address usdv, address vault, address recipient, uint amount) public {
        require(amount > 0);
        c.init(vader, usdv, vault);
        c.newGrantProposal(recipient, amount);
        c.voteProposal(1);
        c.finaliseProposal(1);
        assert(c.VADER() == vader);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() == _vader);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address _vader, address _usdv, address _vault, address proposedAddress) public returns (bool) {
        c.init(_vader, _usdv, _vault);
        c.newAddressProposal(proposedAddress, "UTILS");
        uint pid = c.proposalCount();
        c.voteProposal(pid);
        bool success = !address(c).balance;
        c.finaliseProposal(pid);
        return success;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() != address(0));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(_vader != address(0));
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() != address(0));
    }
}

contract InvMutTest {
    C c;
    bool initReverted;
    constructor(C _c) { c = _c; }
    function test(address _vader, address _usdv, address _vault, address recipient, uint amount) public {
        try c.init(_vader, _usdv, _vault) { initReverted = false; } catch { initReverted = true; }
        if (!initReverted) {
            c.newGrantProposal(recipient, amount);
            try c.finaliseProposal(1) { assert(false); } catch { assert(true); }
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault) public payable {
        require(true);
        c.init(_vader, _usdv, _vault);
        assert(iERC20(_usdv).balanceOf(_vault) > 0);
    }
    receive() external payable {}
}

